"""🔗 Linked work (same reference / by hand), notes kept when converting, full backup file + restore by team, External Follow-up name."""
from harness import app_session, Check, run, SHOTS
async def main():
    c = Check('linked work · notes on convert · full backup')
    async with app_session() as s:
        pg = s.page; J = s.js
        tt = "(L('taskTypes')()[0]||'Support')"; src = "(L('sources')()[0]||'Phone')"
        # ---------- name
        t = await s.go('#/home', 500)
        c('menu says External Follow-up', 'External Follow-up' in await pg.inner_text('nav') and 'Central Follow-up' not in await pg.inner_text('nav'))
        # ---------- links by reference and by hand
        await s.sign_in_as('yousef')
        await J(f"Store.saveMany([{{c:'shadow', id:'wl-a', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:{tt}, source:{src}, subject:'Dose check fix', minutes:60, ref:'REQ-100'}}, {{c:'shadow', id:'wl-b', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:{tt}, source:{src}, subject:'Dose check retest', minutes:30, ref:' req-100 '}}, {{c:'shadow', id:'wl-c', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:{tt}, source:{src}, subject:'Call with pharmacy', minutes:15}}])")
        await pg.wait_for_timeout(200)
        c('same reference does NOT link by itself — it is offered both ways', await J("WorkLinks.of(Store.get('wl-a')).length === 0 && WorkLinks.sameRef(Store.get('wl-a')).some(x => x.id === 'wl-b') && WorkLinks.sameRef(Store.get('wl-b')).some(x => x.id === 'wl-a')"))
        await J(f"Store.saveMany([{{c:'shadow', id:'wl-na1', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:{tt}, source:{src}, subject:'x', minutes:5, ref:'N/A'}}, {{c:'shadow', id:'wl-na2', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:{tt}, source:{src}, subject:'y', minutes:5, ref:'n/a'}}, {{c:'shadow', id:'wl-ph1', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:{tt}, source:{src}, subject:'z', minutes:5, ref:'phone'}}, {{c:'shadow', id:'wl-ph2', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:{tt}, source:{src}, subject:'w', minutes:5, ref:'Phone'}}])")
        c('fillers like N/A or phone are never offered', await J("WorkLinks.sameRef(Store.get('wl-na1')).length === 0 && WorkLinks.sameRef(Store.get('wl-ph1')).length === 0"))
        c('no reference: not linked yet', await J("WorkLinks.of(Store.get('wl-c')).length") == 0)
        await J("UI.editRecord('shadow', Store.get('wl-a'))"); await pg.wait_for_selector('#wlinks')
        c('form offers the same-reference item with 🔗 Link', 'Same reference — not linked' in await pg.inner_text('#wlinks') and await pg.locator('[data-wlref="wl-b"]').count() == 1)
        await pg.click('[data-wlref="wl-b"]'); await pg.wait_for_timeout(300)
        c('one click links it (both ways) and the box shows the time', await J("WorkLinks.of(Store.get('wl-b')).some(x => x.r.id === 'wl-a')") and '1.5 h' in await pg.inner_text('#wlinks') and 'Same reference — not linked' not in await pg.inner_text('#wlinks'))
        await pg.click('[data-wlpick]'); await pg.wait_for_selector('#wlq')
        await pg.fill('#wlq', 'pharmacy'); await pg.wait_for_timeout(150)
        await pg.check('#wllist input[value="wl-c"]'); await pg.click('#modal [data-ok]'); await pg.wait_for_timeout(500)
        c('picked item linked by hand (both ways)', await J("WorkLinks.of(Store.get('wl-c')).some(x => x.r.id === 'wl-a' && x.how === 'hand')"))
        c('back in the form after linking', await pg.locator('#recform').count() == 1 and await pg.locator('#wlinks [data-wldel]').count() == 2)
        await J("UI.closeModal()")
        t = await s.go('#/shadow', 500); c('list shows 🔗 count', '🔗 2' in t)
        # new linked shadow work from an item with no reference → linked by hand
        await J("UI.editRecord('shadow', Store.get('wl-c'))"); await pg.wait_for_selector('[data-wlnew]'); await pg.click('[data-wlnew]'); await pg.wait_for_selector('#recform [name=subject]')
        c('new linked entry filled in', await pg.input_value('#recform [name=subject]') == 'Call with pharmacy')
        if not await pg.input_value('#recform [name=taskType]'): await pg.select_option('#recform [name=taskType]', index=1)
        await pg.click('[data-save]'); await pg.wait_for_timeout(500)
        c('new entry is linked to the item', await J("WorkLinks.of(Store.get('wl-c')).length") == 2,
          await J("JSON.stringify({open: !!document.querySelector('#recform'), toast: (document.querySelector('#toasts')||{}).innerText, links: (Store.byC.worklink||[]).map(l => [l.a, l.b, !!l._del]), shadow: Store.all('shadow','*').map(x => x.id + ':' + x.subject)})"))
        # ---------- notes + links follow a conversion; undo brings them back
        await J("RefNotes.add(Store.get('wl-a'), 'Setting is under Pharmacy > Dose rules')"); await pg.wait_for_timeout(150)
        await J("Conv.open(Store.get('wl-a'), 'quickwin')"); await pg.wait_for_selector('#recform [name=module]')
        await pg.fill('#recform [name=module]', 'Orders'); await pg.click('[data-save]'); await pg.wait_for_timeout(600)
        qid = await J("(Store.all('quickwin', '*').find(q => q.convertedFrom && q.convertedFrom.id === 'wl-a') || {}).id")
        c('converted to a quick win', bool(qid) and await J("Store.get('wl-a')") is None)
        c('note follows the conversion', await J(f"RefNotes.of('{qid}').some(n => n.text.includes('Dose rules'))"))
        c('reference and links follow', await J(f"Store.get('{qid}').ref") == 'REQ-100' and await J(f"(ids => ids.includes('wl-b') && ids.includes('wl-c'))(WorkLinks.of(Store.get('{qid}')).map(x => x.r.id))"))
        await J(f"RefNotes.add(Store.get('{qid}'), 'Added on the quick win')"); await pg.wait_for_timeout(150)
        await J(f"UI.editRecord('quickwin', Store.get('{qid}'))"); await pg.wait_for_selector('[data-cvundo]')
        c('form shows the note', 'Dose rules' in await pg.inner_text('#refnotes'))
        await pg.click('[data-cvundo]'); await pg.wait_for_timeout(500)
        c('undo: notes back on the shadow work (both)', await J("RefNotes.of('wl-a').length") == 2)
        # an item converted before this version: its notes show again
        await J(f"Store.saveMany([{{c:'shadow', id:'wl-old', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:{tt}, source:{src}, subject:'Old one', minutes:10}}])"); await J("RefNotes.add(Store.get('wl-old'), 'Old note')")
        await J("Store.saveMany([Object.assign({}, Store.get('wl-old'), {_del:true, convertedTo:'quickwin'}), {c:'quickwin', id:'wl-oldq', analyst:'yousef', team:'apps', date:U.todayStr(), subject:'Old one', module:'Orders', status:'Completed', convertedFrom:{c:'shadow', id:'wl-old', title:'Old one', by:'yousef', at:1}}])"); await pg.wait_for_timeout(200)
        c('older conversion: note found again', await J("RefNotes.of('wl-oldq').some(n => n.text === 'Old note')"))
        # ---------- text boxes kept as notes (manager converts a To Do)
        await s.sign_in_as('apps-mgr')
        await J("Store.save({c:'todo', id:'wl-t1', analyst:'yousef', team:'apps', task:'Check lab mapping', assigned:U.todayStr(), duration:2, status:'In Progress', instruction:'Use the new LOINC list', comment:'Half done', ref:'SRS-7'})"); await pg.wait_for_timeout(200)
        await J("Conv.open(Store.get('wl-t1'), 'shadow')"); await pg.wait_for_selector('#recform [name=taskType]')
        await pg.select_option('#recform [name=taskType]', index=1); await pg.select_option('#recform [name=source]', index=1); await pg.click('[data-save]'); await pg.wait_for_timeout(600)
        sid = await J("(Store.all('shadow', '*').find(x => x.convertedFrom && x.convertedFrom.id === 'wl-t1') || {}).id")
        c('To Do → shadow keeps the reference', bool(sid) and await J(f"Store.get('{sid}').ref") == 'SRS-7')
        c('instruction and comment kept as notes', await J(f"(t => t.includes('Use the new LOINC list') && t.includes('Half done'))(RefNotes.text('{sid}'))"))
        c('nothing rejected by the trust check', await J("Store.rejected.length") == 0, await J("JSON.stringify(Store.rejected.slice(0,3))"))
        # ---------- full backup file, restore one team from the file
        await s.sign_in_as('adam'); await J("Store.flush()")
        await J("Store.save({c:'todo', id:'wl-keep', analyst:'yousef', team:'apps', task:'In the backup', assigned:U.todayStr(), duration:1, status:'In Progress'})"); await J("Store.flush()")
        nm = await J("Store.downloadFullBackup()")
        c('full backup downloaded', nm.startswith('MAHAM-full-backup-'), nm)
        c('no extra copy left in the Backups folder', not await J("Store.listBackups().then(l => l.some(b => b.name.includes('-download-')))"))
        await J("Store.zipAll().then(z => { window._bk = new File([z.blob], 'MAHAM-full-backup.zip'); })")
        info = await J("Store.readBackup(window._bk).then(x => x.info)")
        c('backup lists the teams', info and any(t['id'] == 'apps' for t in info.get('teams', [])))
        await J("Store.save(Object.assign({}, Store.get('wl-keep'), {_del:true}))"); await J("Store.flush()")
        n = await J("Store.restoreBackup(window._bk, null, ['todo'], ['apps'])")
        c('restore from a file puts the team record back', await J("!!Store.get('wl-keep')") and n > 0, n)
        # ---------- disaster: every data file is gone → restore the whole file into the empty folder
        await J("Store.flush()")
        await J("(async () => { const names = []; for await (const [f, h] of Store.usersDir.entries()) if (h.kind === 'file') names.push(f); for (const f of names) await Store.usersDir.removeEntry(f); Store.sources = {}; Store.own = {}; Store.pending = {}; Store.dirty = false; await Store.sync(true); })()")
        c('(all data files deleted)', await J("Store.folderEmpty()") and await J("!Store.get('wl-keep') && !Store.get('wl-b')"))
        c('super admin can still sign in on the empty folder (built-in start data)', await J("Store.isSuper('adam')"))
        n = await J("Store.restoreBackup(window._bk)")
        await J("Store.sync(true)")
        c('everything is back after restoring into the empty folder', n > 0 and await J("!!Store.get('wl-keep') && !!Store.get('wl-b') && !!Store.get('wl-c')"), n)
        c('settings and links are back too', await J("(Store.byC.worklink || []).length > 0 && (Store.byC.refnote || []).length > 0"))
        c('restored data passes the trust check', await J("Store.rejected.length") == 0, await J("JSON.stringify(Store.rejected.slice(0,3))"))
        await s.go('#/syscheck', 600)
        c('System Check has download + restore from file', await pg.locator('#bkfull').count() == 1 and await pg.locator('#bkup').count() == 1)
        await pg.screenshot(path=f'{SHOTS}/worklinks_backup.png', full_page=True)
        c('no page errors', not s.errors, s.errors[:3])
        c.done(s)

run(main())
